import React from 'react';
import { categories } from '../data/menuData';

function CategoryFilter({ activeCategory, onCategoryChange }) {
  return (
    <div className="flex flex-wrap gap-3 justify-center">
      {categories.map((cat, index) => (
        <button
          key={cat.id}
          onClick={() => onCategoryChange(cat.id)}
          className={`px-5 py-2.5 rounded-full font-semibold text-sm transition-all duration-300 ease-out shadow-md hover:shadow-xl transform hover:scale-105 active:scale-95 ${
            activeCategory === cat.id
              ? 'text-white shadow-lg scale-105'
              : 'bg-white text-gray-700 hover:bg-red-50 hover:text-red-600'
          }`}
          style={{
            background: activeCategory === cat.id
              ? 'linear-gradient(135deg, var(--maroon), var(--saffron))'
              : '',
            animationDelay: `${index * 0.05}s`,
            animation: activeCategory === cat.id ? 'glowPulse 2s ease-in-out infinite' : 'none'
          }}
        >
          <span className="flex items-center gap-2">
            <span>{cat.icon}</span>
            {cat.label}
          </span>
        </button>
      ))}
    </div>
  );
}

export default CategoryFilter;
